resources.transform:
function transform(data) { 
	return data.forEach((row) => {
	    row.description = row.description.replace(/<[^>]*>/g, "")
	    return row
	})
}

watchers.script:
// searchText

if (searchText.value === "") {
    itemsList.value = items.data
} else {
    itemsList.value = items.data.filter(item => 
      item.item_name.toLowerCase().includes(searchText.value.toLowerCase())
    )
}
